+++ b/apps/demo-app/src/config.test.ts
@@ -50,6 +50,17 @@ describe('loadShopSettings', () => {
   it('rejects a bad setting', () => {
     expect(() => loadShopSettings({ MAX_ITEM_QUANTITY: '0' })).toThrow();
   });
+
+  it('rejects a value too large for the integer columns it is stored in', () => {
+    // A money or quantity setting is written to a Postgres `integer` (int4) column, so a
+    // value above 2147483647 would fail the insert with "out of range for type integer".
+    expect(() => loadShopSettings({ SHIPPING_FLAT_CENTS: '2500000000' })).toThrow();
+    expect(() => loadShopSettings({ FREE_SHIPPING_MIN_CENTS: '2500000000' })).toThrow();
+    expect(() => loadShopSettings({ MAX_ITEM_QUANTITY: '2500000000' })).toThrow();
+    expect(loadShopSettings({ SHIPPING_FLAT_CENTS: '2147483647' }).shippingFlatCents).toBe(
+      2147483647,
+    );
+  });
 });

